125	fn handle_cache(action: CacheAction) -> anyhow::Result<()> {
126	    let db_path = paths::db_path();
127	    match action {
128	        CacheAction::Clear => {
129	            if db_path.exists() {
130	                let cache = codeflow_core::dedup::DedupCache::open(&db_path, "")?;
131	                let removed = cache.clear()?;
132	                println!("Cleared {} cache entries.", removed);
133	            } else {
134	                println!("Cache is empty.");
135	            }
136	            Ok(())
137	        }
138	        CacheAction::Info => {
139	            if db_path.exists() {
140	                let cache = codeflow_core::dedup::DedupCache::open(&db_path, "")?;
141	                let count = cache.entry_count()?;
142	                println!("Cache entries: {}", count);
143	                println!("Database: {}", db_path.display());
144	            } else {
145	                println!("No cache database found.");
146	            }
147	            Ok(())
148	        }
149	    }
150	}
