152	fn handle_hook(action: HookAction) -> anyhow::Result<()> {
153	    match action {
154	        HookAction::PreToolUse => {
155	            let input = match read_stdin() {
156	                Ok(s) => s,
157	                Err(e) => {
158	                    eprintln!("[codeflow] hook health-check: stdin read failed: {}", e);
159	                    println!("{{}}");
160	                    return Ok(());
161	                }
162	            };
163	
164	            let parsed: serde_json::Value = match serde_json::from_str(&input) {
165	                Ok(v) => v,
166	                Err(e) => {
167	                    eprintln!("[codeflow] hook health-check: invalid JSON from Claude Code: {}", e);
168	                    println!("{{}}");
169	                    return Ok(());
170	                }
171	            };
172	
173	            if !parsed.is_object() {
174	                eprintln!("[codeflow] hook health-check: expected JSON object, got {}", parsed);
175	                println!("{{}}");
176	                return Ok(());
177	            }
178	
179	            let tool_name = parsed.get("tool_name").and_then(|v| v.as_str());
180	            if tool_name.is_some() && tool_name != Some("Bash") {
181	                println!("{{}}");
182	                return Ok(());
183	            }
184	
185	            if let Some(tool_input) = parsed.get("tool_input") {
186	                if !tool_input.is_object() {
187	                    eprintln!("[codeflow] hook health-check: tool_input is not an object");
188	                    println!("{{}}");
189	                    return Ok(());
190	                }
191	                if let Some(command) = tool_input.get("command").and_then(|c| c.as_str()) {
192	                    if should_wrap(command) {
193	                        let codeflow_bin = std::env::current_exe()
194	                            .unwrap_or_default()
195	                            .to_string_lossy()
196	                            .to_string();
197	                        let rewritten = format!("{} wrap {}", codeflow_bin, command);
198	                        let response = serde_json::json!({
199	                            "tool_input": {
200	                                "command": rewritten
201	                            }
202	                        });
203	                        println!("{}", serde_json::to_string(&response)?);
204	                        return Ok(());
205	                    }
206	                }
207	            }
208	
209	            println!("{{}}");
210	            Ok(())
211	        }
212	        HookAction::PostToolUse => {
213	            println!("{{}}");
214	            Ok(())
215	        }
216	    }
217	}
