219	fn should_wrap(command: &str) -> bool {
220	    let first_word = command.split_whitespace().next().unwrap_or("");
221	    let stem = std::path::Path::new(first_word)
222	        .file_stem()
223	        .and_then(|s| s.to_str())
224	        .unwrap_or(first_word);
225	    let wrappable = [
226	        "git", "npm", "npx", "pnpm", "yarn", "cargo", "pytest", "python",
227	        "tsc", "eslint", "ls", "find", "grep", "cat", "head", "tail",
228	        "docker", "kubectl", "go", "make", "pip", "ruff", "mypy", "vitest",
229	    ];
230	    wrappable.contains(&stem)
231	}
