199	fn stage_strip_ansi(text: &str) -> String {
200	    match strip_ansi_escapes::strip_str(text) {
201	        s if s.is_empty() && !text.is_empty() => text.to_string(),
202	        s => s.to_string(),
203	    }
204	}
205	
206	fn stage_replace(text: &str, rule: &ReplaceRule) -> String {
207	    match Regex::new(&rule.pattern) {
208	        Ok(re) => re.replace_all(text, rule.replacement.as_str()).to_string(),
209	        Err(_) => text.to_string(),
210	    }
211	}
212	
213	fn stage_match_output(text: &str, rule: &MatchOutputRule) -> String {
214	    let re = match Regex::new(&rule.pattern) {
215	        Ok(r) => r,
216	        Err(_) => return text.to_string(),
217	    };
218	    let lines: Vec<&str> = text.lines().collect();
219	    let filtered: Vec<&str> = lines
220	        .into_iter()
221	        .filter(|line| {
222	            let matches = re.is_match(line);
223	            if rule.invert { !matches } else { matches }
224	        })
225	        .collect();
226	    filtered.join("\n")
227	}
228	
229	fn stage_strip_lines(text: &str, rule: &StripLinesRule) -> String {
230	    let re = match Regex::new(&rule.pattern) {
231	        Ok(r) => r,
232	        Err(_) => return text.to_string(),
233	    };
234	    text.lines()
235	        .filter(|line| !re.is_match(line))
236	        .collect::<Vec<_>>()
237	        .join("\n")
238	}
239	
240	fn stage_truncate_lines(text: &str, rule: &TruncateLinesRule) -> String {
241	    text.lines()
242	        .map(|line| {
243	            if line.len() > rule.max_length {
244	                let truncated: String = line.chars().take(rule.max_length).collect();
245	                format!("{}{}", truncated, rule.suffix)
246	            } else {
247	                line.to_string()
248	            }
249	        })
250	        .collect::<Vec<_>>()
251	        .join("\n")
252	}
253	
254	fn stage_head_tail(text: &str, rule: &HeadTailRule) -> String {
255	    let lines: Vec<&str> = text.lines().collect();
256	    let total = lines.len();
257	    if total <= rule.head + rule.tail {
258	        return text.to_string();
259	    }
260	    let head_part: Vec<&str> = lines[..rule.head].to_vec();
261	    let tail_part: Vec<&str> = lines[total - rule.tail..].to_vec();
262	    let omitted = total - rule.head - rule.tail;
263	    let sep = rule.separator.replace("{omitted}", &omitted.to_string());
264	    format!("{}{}{}", head_part.join("\n"), sep, tail_part.join("\n"))
265	}
266	
267	fn stage_max_lines(text: &str, max: usize) -> String {
268	    let lines: Vec<&str> = text.lines().collect();
269	    if lines.len() <= max {
270	        return text.to_string();
271	    }
272	    lines[..max].join("\n")
273	}
