92	fn inject_hooks(settings_json: &str, codeflow_bin: &str) -> Result<String> {
93	    let mut json: serde_json::Value = serde_json::from_str(settings_json)?;
94	
95	    let bin_escaped = codeflow_bin.replace('\\', "\\\\");
96	
97	    let hooks = serde_json::json!({
98	        "PreToolUse": [
99	            {
100	                "matcher": "Bash",
101	                "hooks": [
102	                    {
103	                        "type": "command",
104	                        "command": format!(
105	                            "{} hook pre-tool-use",
106	                            bin_escaped
107	                        )
108	                    }
109	                ]
110	            }
111	        ],
112	        "PostToolUse": [
113	            {
114	                "matcher": "Bash",
115	                "hooks": [
116	                    {
117	                        "type": "command",
118	                        "command": format!(
119	                            "{} hook post-tool-use",
120	                            bin_escaped
121	                        )
122	                    }
123	                ]
124	            }
125	        ]
126	    });
127	
128	    if let Some(existing) = json.get_mut("hooks").and_then(|h| h.as_object_mut()) {
129	        existing.insert("PreToolUse".to_string(), hooks["PreToolUse"].clone());
130	        existing.insert("PostToolUse".to_string(), hooks["PostToolUse"].clone());
131	    } else {
132	        json["hooks"] = hooks;
133	    }
134	
135	    Ok(serde_json::to_string_pretty(&json)?)
136	}
