13	pub fn execute(command_args: &[String]) -> Result<()> {
14	    if command_args.is_empty() {
15	        anyhow::bail!("No command specified");
16	    }
17	
18	    let program = &command_args[0];
19	    let args = &command_args[1..];
20	
21	    let start = Instant::now();
22	    let cmd_output = run_command(program, args)?;
23	    let raw_output = &cmd_output.combined;
24	    let session_id = session_id();
25	    let project_dir = std::env::current_dir()
26	        .unwrap_or_default()
27	        .to_string_lossy()
28	        .to_string();
29	
30	    let result = match compress(raw_output, program, args, &session_id, &project_dir) {
31	        Ok(r) => r,
32	        Err(e) => {
33	            tracing::warn!("compression failed, passing through: {}", e);
34	            print_output(raw_output);
35	            propagate_exit(cmd_output.exit_code);
36	            return Ok(());
37	        }
38	    };
39	
40	    let latency_ms = start.elapsed().as_secs_f64() * 1000.0;
41	    tracing::debug!(
42	        command = program,
43	        input_len = result.filter.input_len,
44	        output_len = result.filter.output_len,
45	        dedup_hit = result.dedup_hit,
46	        latency_ms = latency_ms,
47	        "wrap complete"
48	    );
49	
50	    if result.dedup_hit {
51	        if let Some(summary) = &result.dedup_summary {
52	            print_output(summary);
53	        } else {
54	            print_output(&result.filter.output);
55	        }
56	    } else {
57	        print_output(&result.filter.output);
58	    }
59	
60	    propagate_exit(cmd_output.exit_code);
61	    Ok(())
62	}
